var university = new University("Universidad de Costa Rica", "Costa Rica");
Assert.That(university.Name, Is.EqualTo("Universidad de Costa Rica"));
Assert.That(university.Country, Is.EqualTo("Costa Rica"));

var mockRepo = new Mock<IUniversityRepository>();
mockRepo.Setup(r => r.ExistsByNameAsync("UCR")).ReturnsAsync(false);
var service = new UniversityService(mockRepo.Object);
var result = await service.AddUniversityAsync("Universidad de Costa Rica", "Costa Rica");
Assert.That(result.IsSuccess, Is.True);
mockRepo.Verify(r => r.AddAsync(It.Is<University>(u => u.Name == "Universidad de Costa Rica" && u.Country == "Costa Rica")), Times.Once);

var mockRepo = new Mock<IUniversityRepository>();
mockRepo.Setup(r => r.ExistsByNameAsync("UCR")).ReturnsAsync(true);
var service = new UniversityService(mockRepo.Object);
var result = await service.AddUniversityAsync("UCR", "Costa Rica");
Assert.That(result.IsSuccess, Is.False);
Assert.That(result.ErrorMessage, Does.Contain("already exists"));
mockRepo.Verify(r => r.AddAsync(It.IsAny<University>()), Times.Never);

var mockRepo = new Mock<IUniversityRepository>();
var service = new UniversityService(mockRepo.Object);
var result = await service.AddUniversityAsync("", "Costa Rica");
Assert.That(result.IsSuccess, Is.False);
Assert.That(result.ErrorMessage, Does.Contain("Name"));
mockRepo.Verify(r => r.AddAsync(It.IsAny<University>()), Times.Never);

var mockRepo = new Mock<IUniversityRepository>();
var service = new UniversityService(mockRepo.Object);
var result = await service.AddUniversityAsync("Universidad de Costa Rica", "");
Assert.That(result.IsSuccess, Is.False);
Assert.That(result.ErrorMessage, Does.Contain("Country"));
mockRepo.Verify(r => r.AddAsync(It.IsAny<University>()), Times.Never);

var mockDbContext = new Mock<UCRDatabaseContext>();
var mockDbSet = new Mock<DbSet<University>>();
mockDbContext.Setup(c => c.Universities).Returns(mockDbSet.Object);
var repository = new SqlUniversityRepository(mockDbContext.Object);
var university = new University("UCR", "Costa Rica");
await repository.AddAsync(university);
mockDbSet.Verify(d => d.AddAsync(university, It.IsAny<CancellationToken>()), Times.Once);
mockDbContext.Verify(c => c.SaveChangesAsync(It.IsAny<CancellationToken>()), Times.Once);

var mockDbContext = new Mock<UCRDatabaseContext>();
var universities = new List<University> { new University("UCR", "Costa Rica") }.AsQueryable();
var mockDbSet = new Mock<DbSet<University>>();
mockDbSet.As<IQueryable<University>>().Setup(m => m.Provider).Returns(universities.Provider);
mockDbSet.As<IQueryable<University>>().Setup(m => m.Expression).Returns(universities.Expression);
mockDbSet.As<IQueryable<University>>().Setup(m => m.ElementType).Returns(universities.ElementType);
mockDbSet.As<IQueryable<University>>().Setup(m => m.GetEnumerator()).Returns(universities.GetEnumerator());
mockDbContext.Setup(c => c.Universities).Returns(mockDbSet.Object);
var repository = new SqlUniversityRepository(mockDbContext.Object);
var result = await repository.ExistsByNameAsync("UCR");
Assert.That(result, Is.True);

var mockDbContext = new Mock<UCRDatabaseContext>();
var universities = new List<University>().AsQueryable();
var mockDbSet = new Mock<DbSet<University>>();
mockDbSet.As<IQueryable<University>>().Setup(m => m.Provider).Returns(universities.Provider);
mockDbSet.As<IQueryable<University>>().Setup(m => m.Expression).Returns(universities.Expression);
mockDbSet.As<IQueryable<University>>().Setup(m => m.ElementType).Returns(universities.ElementType);
mockDbSet.As<IQueryable<University>>().Setup(m => m.GetEnumerator()).Returns(universities.GetEnumerator());
mockDbContext.Setup(c => c.Universities).Returns(mockDbSet.Object);
var repository = new SqlUniversityRepository(mockDbContext.Object);
var result = await repository.ExistsByNameAsync("UCR");
Assert.That(result, Is.False);

var mockService = new Mock<IUniversityService>();
mockService.Setup(s => s.AddUniversityAsync("UCR", "Costa Rica")).ReturnsAsync(Result.Success());
var handler = new AddUniversityHandler(mockService.Object);
var result = await handler.HandleAsync("UCR", "Costa Rica");
Assert.That(result.Result, Is.TypeOf<Ok<AddUniversityResponse>>());
var okResult = result.Result as Ok<AddUniversityResponse>;
Assert.That(okResult.Value.Message, Is.EqualTo("University added successfully"));

var mockService = new Mock<IUniversityService>();
mockService.Setup(s => s.AddUniversityAsync("UCR", "Costa Rica")).ReturnsAsync(Result.Failure("University with name 'UCR' already exists"));
var handler = new AddUniversityHandler(mockService.Object);
var result = await handler.HandleAsync("UCR", "Costa Rica");
Assert.That(result.Result, Is.TypeOf<BadRequest<string>>());
var badRequestResult = result.Result as BadRequest<string>;
Assert.That(badRequestResult.Value, Does.Contain("already exists"));

var mockService = new Mock<IUniversityService>();
mockService.Setup(s => s.AddUniversityAsync("", "Costa Rica")).ReturnsAsync(Result.Failure("Name is required"));
var handler = new AddUniversityHandler(mockService.Object);
var result = await handler.HandleAsync("", "Costa Rica");
Assert.That(result.Result, Is.TypeOf<BadRequest<string>>());
var badRequestResult = result.Result as BadRequest<string>;
Assert.That(badRequestResult.Value, Does.Contain("required"));
